import pytest
from string_utils import reverse_string, count_vowels, is_palindrome, truncate

def test_reverse_string_empty():
    assert reverse_string("") == ""

def test_reverse_string_single_character():
    assert reverse_string("a") == "a"

def test_reverse_string_normal():
    assert reverse_string("hello") == "olleh"

def test_reverse_string_with_spaces():
    assert reverse_string("hello world") == "dlrow olleh"

def test_reverse_string_with_special_characters():
    assert reverse_string("!@#$") == "$#@!"

def test_reverse_string_numbers():
    assert reverse_string("12345") == "54321"

def test_count_vowels_empty():
    assert count_vowels("") == 0

def test_count_vowels_no_vowels():
    assert count_vowels("rhythm") == 1
    assert count_vowels("xyz") == 0
    assert count_vowels("brrgh") == 0

def test_count_vowels_all_vowels_lower():
    assert count_vowels("aeiouy") == 6

def test_count_vowels_all_vowels_upper():
    assert count_vowels("AEIOUY") == 6

def test_count_vowels_mixed_case():
    assert count_vowels("HeLlO wOrLd") == 3

def test_count_vowels_with_numbers_and_symbols():
    assert count_vowels("123!@#aeiou") == 5

def test_count_vowels_long_string():
    assert count_vowels("The quick brown fox jumps over the lazy dog.") == 12 # o,u,i,o,o,u,o,e,e,a,o

def test_count_vowels_only_y():
    assert count_vowels("myths") == 1
    assert count_vowels("why") == 1

def test_is_palindrome_empty():
    assert is_palindrome("")

def test_is_palindrome_single_char():
    assert is_palindrome("a")

def test_is_palindrome_single_non_alphanum():
    assert is_palindrome("!")

def test_is_palindrome_all_non_alphanum():
    assert is_palindrome("!@#$")

def test_is_palindrome_simple_true_lower():
    assert is_palindrome("racecar")

def test_is_palindrome_simple_true_mixed_case():
    assert is_palindrome("Racecar")

def test_is_palindrome_simple_false():
    assert not is_palindrome("hello")

def test_is_palindrome_with_spaces_and_punctuation_true():
    assert is_palindrome("A man, a plan, a canal: Panama")

def test_is_palindrome_with_spaces_and_punctuation_false():
    assert not is_palindrome("No lemon, no melon but not a palindrome.")

def test_is_palindrome_numbers_true():
    assert is_palindrome("12321")

def test_is_palindrome_numbers_false():
    assert not is_palindrome("12345")

def test_is_palindrome_complex_with_numbers_and_punctuation():
    assert is_palindrome("Eva, can I see bees in a cave?")
    assert is_palindrome("2002")

def test_is_palindrome_non_string_input_type_check():
    # This test case checks behavior for non-string input,
    # expecting it to be handled by Python's type system or raise an error.
    # The current implementation will raise an AttributeError as `isalnum`
    # or `lower` cannot be called on non-string items within the generator.
    with pytest.raises(AttributeError):
        is_palindrome(None)

def test_truncate_no_truncation():
    assert truncate("hello", 10) == "hello"

def test_truncate_exact_length():
    assert truncate("hello", 5) == "hello"

def test_truncate_standard_case():
    assert truncate("hello world", 5) == "hello..."

def test_truncate_custom_suffix():
    assert truncate("hello world", 5, "---") == "hello---"

def test_truncate_empty_string():
    assert truncate("", 5) == ""

def test_truncate_empty_string_max_length_zero():
    assert truncate("", 0) == ""

def test_truncate_string_long_max_length_zero():
    assert truncate("hello", 0) == "..."

def test_truncate_string_long_max_length_one():
    assert truncate("hello", 1) == "h..."

def test_truncate_suffix_is_empty_string():
    assert truncate("hello world", 5, "") == "hello"

def test_truncate_suffix_is_longer_than_max_length_value():
    # max_length refers to the prefix before suffix is appended
    assert truncate("short string", 2, "LONG_SUFFIX") == "shLONG_SUFFIX"

def test_truncate_max_length_equal_to_string_length():
    test_string = "abcdefg"
    assert truncate(test_string, len(test_string)) == test_string

def test_truncate_max_length_just_one_less_than_string_length():
    test_string = "abcdefg"
    assert truncate(test_string, len(test_string) - 1) == "abcdef..."

def test_truncate_string_contains_suffix_content():
    assert truncate("This string has ... inside", 10) == "This strin..."
    assert truncate("This string has ... inside", 25) == "This string has ... inside"

